import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 100.5)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for normal order", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(799);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal >= freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns flat fee when subtotal < freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(799);
    });

    it("returns 0 when subtotal exceeds freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 10000)).toBe(0);
    });

    it("charges flat fee when freeOverCents is not configured", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100000)).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow();
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 3)], 5000),
      ).toBe(0);
    });

    it("selects first bracket when weight <= smallest upToGrams", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 250, 2)], 5000),
      ).toBe(300); // 500g
    });

    it("selects bracket at exact boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 5000),
      ).toBe(300); // exactly 500g
    });

    it("selects middle bracket", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 5000),
      ).toBe(700); // 501g → bracket 2000
    });

    it("selects highest bracket at boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 5000, 1)], 5000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 5001, 1)], 5000),
      ).toBe(2000);
    });

    it("defaults to heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      expect(
        noOverflow.computeShippingCents([makeLine("a", 5000, 1)], 5000),
      ).toBe(900);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      expect(
        unsorted.computeShippingCents([makeLine("a", 400, 1)], 5000),
      ).toBe(300);
    });

    it("accumulates weight across multiple lines", () => {
      const lines = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
      // total weight = 600 + 500 = 1100 → bracket 2000
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500, weightGrams: 300 };

describe("Cart - line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 5)).toThrow();
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
    // Mutating snapshot doesn't affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline", () => {
  it("subtotal sums unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 3); // 7500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(9500);
  });

  it("discount is applied from the policy", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 5); // subtotal = 5000
    const totals = cart.totals();
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(5000);
    expect(totals.discountCents).toBe(500);
  });

  it("discount is clamped to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBeGreaterThanOrEqual(0);
  });

  it("negative discount is clamped to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(productA, 1); // subtotal = 1000, discount = 200, discounted = 800
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("shipping receives lines and discounted subtotal", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(productA, 2); // subtotal = 2000, discount = 300, discounted = 1700
    const totals = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1700,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 1000,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => 400,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(productA, 5); // subtotal = 5000, discount = 1000, discounted = 4000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(5000);
    expect(totals.discountCents).toBe(1000);
    expect(totals.taxCents).toBe(400);
    expect(totals.shippingCents).toBe(500);
    expect(totals.totalCents).toBe(4900); // 4000 + 400 + 500
  });

  it("empty cart has all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("defaults to US region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("negative tax from calculator is clamped to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping from calculator is clamped to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    });

    it("throws when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws when fetcher returns non-integer", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("service down");
    });
  });

  describe("inventory check", () => {
    it("succeeds when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 2 }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 3 }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(3);
      }
    });

    it("uses custom reason from decision", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow("discontinued");
    });

    it("checks all items and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true, availableQuantity: 100 })
          .mockResolvedValueOnce({ available: false, availableQuantity: 0 }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 10); // subtotal = 10000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.taxCents).toBe(1000); // 10% of 10000
    });

    it("async tax is computed on discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "FR",
      });
      cart.add(productA, 10); // subtotal = 10000, discount = 2000, discounted = 8000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(1600); // 20% of 8000
    });

    it("propagates async tax rate error", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service unavailable")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service unavailable",
      );
    });

    it("throws when async provider returns invalid rate", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(productA, 2);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve(1200);
          return Promise.resolve(2500);
        }),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 50 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Subtotal: 1200*2 + 2500*1 = 4900
      expect(result.totals.subtotalCents).toBe(4900);
      // Discount: 10% of 4900 = 490
      expect(result.totals.discountCents).toBe(490);
      // Discounted: 4900 - 490 = 4410
      // Tax: 8% of 4410 = 352.8 → floor = 352
      expect(result.totals.taxCents).toBe(352);
      // Shipping: flat 500
      expect(result.totals.shippingCents).toBe(500);
      // Total: 4410 + 352 + 500 = 5262
      expect(result.totals.totalCents).toBe(5262);
    });

    it("checkout without collaborators uses sync totals", async () => {
      const cart = new Cart();
      cart.add(productA, 3);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.totals.totalCents).toBe(3000);
    });

    it("returns refreshed lines in result", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(9999);
    });
  });
});

describe("InventoryError", () => {
  it("has expected shape", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("available can be undefined", () => {
    const err = new InventoryError("gone", "prod-2", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});

import { describe, it, expect, vi } from "vitest";
import { refreshPrices } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "a", name: "A", unitPriceCents: 1000 }, quantity: 2 },
    { product: { id: "b", name: "B", unitPriceCents: 2000 }, quantity: 1 },
  ];

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) => {
        if (id === "a") return Promise.resolve(1500);
        return Promise.resolve(2500);
      }),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(1500);
    expect(result[1]!.product.unitPriceCents).toBe(2500);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const linesWithWeight: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 1000, weightGrams: 500 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
