toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 100.5)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for normal order", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(799);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal >= freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns flat fee when subtotal < freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(799);
    });

    it("returns 0 when subtotal exceeds freeOverCents", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 10000)).toBe(0);
    });

    it("charges flat fee when freeOverCents is not configured", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100000)).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow();
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 3)], 5000),
      ).toBe(0);
    });

    it("selects first bracket when weight <= smallest upToGrams", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 250, 2)], 5000),
      ).toBe(300); // 500g
    });

    it("selects bracket at exact boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 5000),
      ).toBe(300); // exactly 500g
    });

    it("selects middle bracket", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 5000),
      ).toBe(700); // 501g → bracket 2000
    });

    it("selects highest bracket at boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 5000, 1)], 5000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 5001, 1)], 5000),
      ).toBe(2000);
    });

    it("defaults to heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      expect(
        noOverflow.computeShippingCents([makeLine("a", 5000, 1)], 5000),
      ).toBe(900);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      expect(
        unsorted.computeShippingCents([makeLine("a", 400, 1)], 5000),
      ).toBe(300);
    });

    it("accumulates weight across multiple lines", () => {
      const lines = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
      // total weight = 600 + 500 = 1100 → bracket 2000
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });
  });
});

