toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500, weightGrams: 300 };

describe("Cart - line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 5)).toThrow();
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
    // Mutating snapshot doesn't affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline", () => {
  it("subtotal sums unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 3); // 7500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(9500);
  });

  it("discount is applied from the policy", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 5); // subtotal = 5000
    const totals = cart.totals();
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(5000);
    expect(totals.discountCents).toBe(500);
  });

  it("discount is clamped to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBeGreaterThanOrEqual(0);
  });

  it("negative discount is clamped to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(productA, 1); // subtotal = 1000, discount = 200, discounted = 800
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("shipping receives lines and discounted subtotal", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(productA, 2); // subtotal = 2000, discount = 300, discounted = 1700
    const totals = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1700,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 1000,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => 400,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(productA, 5); // subtotal = 5000, discount = 1000, discounted = 4000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(5000);
    expect(totals.discountCents).toBe(1000);
    expect(totals.taxCents).toBe(400);
    expect(totals.shippingCents).toBe(500);
    expect(totals.totalCents).toBe(4900); // 4000 + 400 + 500
  });

  it("empty cart has all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("defaults to US region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("negative tax from calculator is clamped to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping from calculator is clamped to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

