toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    });

    it("throws when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws when fetcher returns non-integer", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("service down");
    });
  });

  describe("inventory check", () => {
    it("succeeds when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 2 }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 3 }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(3);
      }
    });

    it("uses custom reason from decision", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow("discontinued");
    });

    it("checks all items and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true, availableQuantity: 100 })
          .mockResolvedValueOnce({ available: false, availableQuantity: 0 }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax calculation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 10); // subtotal = 10000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.taxCents).toBe(1000); // 10% of 10000
    });

    it("async tax is computed on discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "FR",
      });
      cart.add(productA, 10); // subtotal = 10000, discount = 2000, discounted = 8000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(1600); // 20% of 8000
    });

    it("propagates async tax rate error", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service unavailable")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service unavailable",
      );
    });

    it("throws when async provider returns invalid rate", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(productA, 2);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve(1200);
          return Promise.resolve(2500);
        }),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 50 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Subtotal: 1200*2 + 2500*1 = 4900
      expect(result.totals.subtotalCents).toBe(4900);
      // Discount: 10% of 4900 = 490
      expect(result.totals.discountCents).toBe(490);
      // Discounted: 4900 - 490 = 4410
      // Tax: 8% of 4410 = 352.8 → floor = 352
      expect(result.totals.taxCents).toBe(352);
      // Shipping: flat 500
      expect(result.totals.shippingCents).toBe(500);
      // Total: 4410 + 352 + 500 = 5262
      expect(result.totals.totalCents).toBe(5262);
    });

    it("checkout without collaborators uses sync totals", async () => {
      const cart = new Cart();
      cart.add(productA, 3);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.totals.totalCents).toBe(3000);
    });

    it("returns refreshed lines in result", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(9999),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(9999);
    });
  });
});

describe("InventoryError", () => {
  it("has expected shape", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("available can be undefined", () => {
    const err = new InventoryError("gone", "prod-2", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});

